'use strict'

// The dungeon tiles have the colours of their level, as in the ROM: one sprite per level (dungeon_floor_level3 is
// dungeon_floor in level 3). The maps keep the plain name, the level they are in gives the colours
const LEVEL_SUFFIX = /_level[1-9]$/

export function plainName (name) {
  return name?.replace(LEVEL_SUFFIX, '')
}

// The name of the sprite of a tile in a map of this type: the colours of a level when the tile has them
export function mapSpriteNames (name, type) {
  const plain = plainName(name)
  return [`${plain}_${type}`, plain]
}

// The level whose colours a sprite has (undefined: the same in every map)
export function levelOf (name) {
  return name?.match(/_(level[1-9])$/)?.[1]
}
