'use strict'

import { ITEM_SHIELD_NORMAL, ITEM_RING_GREEN, INVENTORY_MAX_RUPEES, INVENTORY_MAX_KEYS, INVENTORY_MAX_BOMBS, ITEM_RED_POTION, ITEM_BLUE_POTION, ITEM_BOMB, ARROW_SILVER, ITEM_SILVER_ARROW, ITEM_WOODEN_ARROW, ITEM_WHISTLE, ITEM_BAIT, ITEM_LETTER, ITEM_WAND } from '../constant'

class Inventory {
  constructor () {
    this.shield = ITEM_SHIELD_NORMAL
    this.ring = ITEM_RING_GREEN
    this.arrow = undefined
    this.bookOfMagic = undefined
    this.ladder = undefined
    this.magicalKey = undefined
    this.powerBracelet = undefined
    this.candle = undefined
    this.bait = false
    this.whistle = false
    this.bow = false
    // The best boomerang owned (ITEM_WOODEN_BOOMERANG, ITEM_MAGICAL_BOOMERANG)
    this.boomerang = undefined
    this.wand = false
    this.raft = false
    // The levels (1 to 8) whose piece of the Triforce Link has: where the whirlwind of the whistle goes
    this.triforce = []
    // The levels whose map and compass Link has
    this.maps = []
    this.compasses = []
    // The letter of the old man, shown once to the old woman to open the potion shops
    this.letter = false
    this.letterShown = false
    // Uses of potion left: 2 for the red one, 1 for the blue one
    this.potion = 0

    this.rupees = 0
    this.keys = 0
    this.bombs = 0
    this.maxRupees = INVENTORY_MAX_RUPEES
    this.maxKeys = INVENTORY_MAX_KEYS
    this.maxBombs = INVENTORY_MAX_BOMBS[0]
  }

  // The potion owned: red while it has two uses left
  get potionName () {
    if (this.potion <= 0) {
      return undefined
    }
    return this.potion >= 2 ? ITEM_RED_POTION : ITEM_BLUE_POTION
  }

  // The 8 places of the items of the B button, in the order of the original inventory: boomerang, bombs, bow and
  // arrows, candle, whistle, bait, letter or potion, wand. Each holds the name of the item owned there, if any
  // (the bow and the arrows are one item of B, shown as the arrow, when Link has both)
  get bItems () {
    return [
      this.boomerang,
      this.bombs > 0 ? ITEM_BOMB : undefined,
      this.bow && this.arrow ? (this.arrow === ARROW_SILVER ? ITEM_SILVER_ARROW : ITEM_WOODEN_ARROW) : undefined,
      this.candle,
      this.whistle ? ITEM_WHISTLE : undefined,
      this.bait ? ITEM_BAIT : undefined,
      this.potionName ?? (this.letter ? ITEM_LETTER : undefined),
      this.wand ? ITEM_WAND : undefined
    ]
  }
}

export { Inventory }
