'use strict'

import InputManager from '../service/input-manager'
import resource from '../resource'
import textManager from '../service/text-manager'
import { listenMenuKeys } from './menu-keys'
import { SPRITE_TEXT_COLOR_WHITE, SPRITE_TEXT_WIDTH, SPRITE_TEXT_HEIGHT } from '../constant'

const MENU_X = 192
const MENU_Y = 176
const LINE_HEIGHT = 64

// After the game over: continue (from the start, with all the items) or retry (back to the title, new
// game). The heart shows the choice, moved with up / down and confirmed with Start, as on the NES.
// No "save" yet: the game is not saved
class GameOverMenu {
  constructor (onContinue, onRetry) {
    this.options = [
      { label: 'continue', choose: onContinue },
      { label: 'retry', choose: onRetry }
    ]
    this.selection = 0
    this.stopListening = listenMenuKeys({
      [InputManager.ACTION_LINK_MOVE_NORTH]: () => this.move(-1),
      [InputManager.ACTION_LINK_MOVE_SOUTH]: () => this.move(1),
      [InputManager.ACTION_START]: () => this.choose()
    })
  }

  move (delta) {
    this.selection = (this.selection + delta + this.options.length) % this.options.length
  }

  choose () {
    this.dispose()
    this.options[this.selection].choose()
  }

  dispose () {
    this.stopListening?.()
    this.stopListening = undefined
  }

  draw (context, width, height) {
    context.fillStyle = 'black'
    context.fillRect(0, 0, width, height)
    this.options.forEach((option, i) => {
      const y = MENU_Y + i * LINE_HEIGHT
      textManager.drawLine(context, option.label, SPRITE_TEXT_COLOR_WHITE, MENU_X, y)
      if (i === this.selection) {
        resource.getSprite('menu_heart_full')?.draw(context, MENU_X - 2 * SPRITE_TEXT_WIDTH, y, SPRITE_TEXT_WIDTH, SPRITE_TEXT_HEIGHT)
      }
    })
  }
}

export { GameOverMenu }
