'use strict'

import resource from '../../resource'
import { TILE_WIDTH, TILE_HEIGHT, ENEMY_TEKTITE_RED, ENEMY_TEKTITE_BLUE } from '../../constant'
import { Enemy, randomInt, drawImage } from './common'

// Spiders that jump from a free place to another one nearby, over the obstacles. The red ones jump
// more often. Rest in steps
const TEKTITES = {
  [ENEMY_TEKTITE_RED]: { color: 'red', life: 1, contactDamage: 0.5, minRest: 10, maxRest: 40 },
  [ENEMY_TEKTITE_BLUE]: { color: 'blue', life: 1, contactDamage: 0.5, minRest: 30, maxRest: 90 }
}
const JUMP_STEPS = 32
const JUMP_HEIGHT = 2 * TILE_HEIGHT
// How far a jump goes, in tiles
const JUMP_RANGE = 3
const TRIES = 8

const STATE_RESTING = 'resting'
const STATE_JUMPING = 'jumping'

class Tektite extends Enemy {
  constructor (type, x, y, random = Math.random) {
    const config = TEKTITES[type]
    super(type, x, y, config, random)
    this.config = config
    this.rest = 0
    this.from = undefined
    this.to = undefined
  }

  start () {
    this.restABit()
  }

  restABit () {
    this.setState(STATE_RESTING)
    this.rest = randomInt(this.random, this.config.minRest, this.config.maxRest)
  }

  // A free place a few tiles away, on the tile grid; none: no jump this time
  target (map) {
    for (let i = 0; i < TRIES; i++) {
      const x = this.x + randomInt(this.random, -JUMP_RANGE, JUMP_RANGE) * TILE_WIDTH
      const y = this.y + randomInt(this.random, -JUMP_RANGE, JUMP_RANGE) * TILE_HEIGHT
      if ((x !== this.x || y !== this.y) && this.canStandAt(map, x, y)) {
        return { x, y }
      }
    }
    return undefined
  }

  act (map) {
    switch (this.state) {
      case STATE_RESTING:
        if (this.steps >= this.rest) {
          this.to = this.target(map)
          if (!this.to) {
            this.restABit()
            return
          }
          this.from = { x: this.x, y: this.y }
          this.setState(STATE_JUMPING)
        }
        break
      case STATE_JUMPING: {
        // Along a straight line, raised by an arc
        const t = Math.min(1, this.steps / JUMP_STEPS)
        this.x = Math.round(this.from.x + (this.to.x - this.from.x) * t)
        this.y = Math.round(this.from.y + (this.to.y - this.from.y) * t - Math.sin(Math.PI * t) * JUMP_HEIGHT)
        if (t >= 1) {
          this.restABit()
        }
        break
      }
    }
  }

  // Not pushed back (measured in the ROM); hit in the air, it lands where it was going
  knockBack (map) {
    if (this.resumeState === STATE_JUMPING) {
      this.x = this.to.x
      this.y = this.to.y
      this.resumeState = STATE_RESTING
      this.rest = this.config.minRest
    }
  }

  drawBody (context) {
    const frame = this.state === STATE_JUMPING ? 1 : 0
    drawImage(context, resource.getSprite(`tektite_${this.config.color}_move`), frame, this.x, this.y, this.width, this.height)
  }
}

export { Tektite, TEKTITES }
