'use strict'

import soundManager from '../service/sound-manager'
import resource from '../resource'
import { MAP_TYPE_WORLD, SOUND_SECRET } from '../constant'

// The lost woods (1,6) and the lost hills (11,1), read in the ROM (bank 1 $AD9F, run from the RAM of the cartridge):
// leaving them by the ways of their list, in order, Link comes back on the same screen ($EC = $EB) and the count of
// the ways ($052F) goes up; the last one, the sound of the secret, and he goes on to the next screen. Any other way
// starts the count again and brings him back, but one: east from the woods, west from the hills, he goes on as from
// any screen, the count kept. Leaving any other screen, the count starts again. What a screen asks is in its data,
// map.lostPath: { ways: ['north', 'west', 'south', 'west'], out: 'east' } (see docs/data-format.md)

let count = 0

// A new game
export function resetLostPaths () {
  count = 0
}

// Link leaves the screen that way: true when he comes back on it
export function backOnLostPath (map, direction) {
  const path = map.type === MAP_TYPE_WORLD ? map.lostPath : undefined
  if (!path?.ways?.length) {
    count = 0
    return false
  }
  if (direction === path.ways[count]) {
    if (count === path.ways.length - 1) {
      soundManager.play(resource.getSound(SOUND_SECRET))
      return false
    }
    count++
    return true
  }
  if (direction === path.out) {
    return false
  }
  count = 0
  return true
}

// The same screen drawn as the next one while it scrolls in (see MapDrag): its scenery only
export function screenAgain (map) {
  return {
    offsetX: 0,
    offsetY: 0,
    draw (context) {
      context.save()
      context.translate(this.offsetX, this.offsetY)
      for (const tile of map.tilesIterator()) {
        tile.draw(context)
      }
      context.restore()
    }
  }
}
